#include <linux/sched.h>
#include <linux/audit.h>
#include <linux/err.h>

int apparmor_setprocattr(struct task_struct *task, char *name, void *value, size_t size) {
    if (!size || task != current) {
        return -EINVAL;
    }

    if (!value || *(char *)value == '\0') {
        return -EINVAL;
    }

    if (strcmp(name, "current") == 0) {
        int ret = 0;
        char *cmd = value;
        if (strcmp(cmd, "changehat") == 0) {
            ret = apparmor_change_hat();
        } else if (strcmp(cmd, "changecomp") == 0) {
            ret = apparmor_change_compline();
        } else {
            audit_log(current->audit_context, AUDIT_APPARMOR, "invalid command", 0, "command", cmd, 0);
            return -EINVAL;
        }
        if (ret < 0) {
            audit_log(current->audit_context, AUDIT_APPARMOR, "error", 0, "command", cmd, 0);
            return ret;
        }
        return size;
    }

    audit_log(current->audit_context, AUDIT_APPARMOR, "invalid attribute", 0, "attribute", name, 0);
    return -EINVAL;
}

int set_task_attr(struct task_struct *task, char *name, void *value, size_t size)
{
    int ret = 0;

    if (size == 0)
        return -EINVAL;

    if (task != current)
        return -EPERM;

    if (!value)
        return -EFAULT;

    if (strnlen(name, AA_NAME_MAX) == AA_NAME_MAX)
        return -ENAMETOOLONG;

    if (strncmp(name, "profile", sizeof("profile") - 1) == 0) {
        if (value && size >= 1) {
            char *cmd = value;
            if (cmd[0] == 'c') {
                ret = aa_change_profile(task, cmd + 1, 0);
            } else if (cmd[0] == 'r') {
                ret = aa_change_profile(task, cmd + 1, 1);
            } else {
                ret = -EINVAL;
            }
        } else {
            ret = -EINVAL;
        }
    } else if (strncmp(name, "perm", sizeof("perm") - 1) == 0) {
        if (value && size >= 1) {
            char *cmd = value;
            if (cmd[0] == 'a') {
                ret = aa_set_perms(task, 1);
            } else if (cmd[0] == 'd') {
                ret = aa_set_perms(task, 0);
            } else {
                ret = -EINVAL;
            }
        } else {
            ret = -EINVAL;
        }
    } else {
        ret = -EINVAL;
    }

    if (ret < 0) {
        audit_log(current->audit_context, AUDIT_AA_SETATTR_FAILURE,
                  "name=%s op=deny", name);
    }

    if (ret >= 0)
        ret = (int)size;

    return ret;
}

#include <linux/sched.h>
#include <linux/cred.h>
#include <linux/audit.h>

int set_apparmor_process_attr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0)
        return -EINVAL;

    if (current != task) {
        return -EPERM;
    }

    if (!value || !*((char *)value)) {
        return -EINVAL;
    }

    if (strcmp(name, "profile") == 0) {
        int ret = set_apparmor_profile(task, value);
        if (ret < 0) {
            audit_log(current->audit_context, AUDIT_APPARMOR, "Failed to set profile", 0);
            return ret;
        }
    } else if (strcmp(name, "permission") == 0) {
        int ret = set_apparmor_permissions(task, value);
        if (ret < 0) {
            audit_log(current->audit_context, AUDIT_APPARMOR, "Failed to set permissions", 0);
            return ret;
        }
    } else {
        return -EINVAL;
    }

    return size;
}

#include <linux/sched.h>
#include <linux/errno.h>
#include <linux/string.h>

int set_task_attr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || task == NULL)
        return -EINVAL;

    if (current != task)
        return -EPERM;

    if (value == NULL || strlen((char *)value) == 0)
        return -EINVAL;

    if (strncmp(name, "profile", sizeof("profile")) == 0) {
        int ret = aa_change_profile(task, value, size);
        if (ret < 0)
            return ret;
    } else if (strncmp(name, "permissions", sizeof("permissions")) == 0) {
        int ret = aa_set_perms(task, value, size);
        if (ret < 0)
            return ret;
    } else {
        return -ENOTSUPP;
    }

    return (int)size;
}

#include <linux/sched.h>
#include <linux/errno.h>
#include <linux/audit.h>

int set_apparmor_process_attr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0)
        return -EINVAL;

    if (current != task)
        return -EPERM;

    if (!value || !*((char *)value))
        return -EFAULT;

    if (strcmp(name, "profile") == 0) {
        int ret = set_apparmor_profile(task, value);
        if (ret < 0) {
            audit_log_untrustedstring(value, audit_buffer);
            return ret;
        }
    } else if (strcmp(name, "mode") == 0) {
        int ret = set_apparmor_mode(task, value);
        if (ret < 0) {
            audit_log_untrustedstring(value, audit_buffer);
            return ret;
        }
    } else {
        return -EINVAL;
    }

    return size;
}
